#include <stdio.h>



int main(void) {
    int n;
    double distance = 100, height = 50;
    scanf("%d", &n);
    for (int i = 1; i < n; i++) { distance += 2 * height; height /= 2; }
    printf("%.6f\n", distance);
    return 0;
}
